class Validate{constructor(){}static validateData(t){let e=0;for(let r=0;r<t.length;r++)t[r]?0==t[r].trim().length&&(e+=1):e+=1;return!(e>0)}static validateFields(t){const e=[];return t.forEach(t=>{const r=t.value;null!=r&&""!==String(r).trim()||e.push(t.label)}),e}static validateTodoList(t){let e=0;for(let r=0;r<t.length;r++)for(let a=0;a<t[r].length;a++){let n=t[r][a].trim();0==n.length&&(e+=1)}return!(e>0)}static allowInputNum(t=[]){t.forEach(t=>{$(t).bind("keypress",function(t){var e=new RegExp("^[0-9]+$"),r=String.fromCharCode(t.charCode?t.charCode:t.which);if(!e.test(r))return t.preventDefault(),!1})})}static allowInputStringSpace(t=[]){t.forEach(t=>{$(t).bind("keypress",function(t){var e=new RegExp("^[a-zA-Z- ]+$"),r=String.fromCharCode(t.charCode?t.charCode:t.which);if(!e.test(r))return t.preventDefault(),!1})})}static allowInputAlphaNum(t=[]){t.forEach(t=>{$(t).bind("keypress",function(t){var e=new RegExp("^[a-zA-Z0-9- ]+$"),r=String.fromCharCode(t.charCode?t.charCode:t.which);if(!e.test(r))return t.preventDefault(),!1})})}static allowInputMoney(t=[]){t.forEach(t=>{$(t).bind("keypress",function(t){var e=new RegExp("^[0-9.]+$"),r=String.fromCharCode(t.charCode?t.charCode:t.which);if(!e.test(r))return t.preventDefault(),!1})})}}export{Validate};